```json
{
  "title": "Đà Lạt Trong Nhà, Mưa Cũng Vui",
  "summary": "Trời mưa thì mình đổi gió: một ngày quanh khu trung tâm, ăn ngon, uống cà phê và ngắm Đà Lạt qua những mái nhà, không ướt một sợi lông.",
  "stops": [
    {
      "poi_id": "p179",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bữa trưa ấm bụng với bánh căn nóng hổi, ngồi trong quán nghe mưa rơi ngoài hiên."
    },
    {
      "poi_id": "p23",
      "kind": "activity",
      "must_do_id": null,
      "note": "Bảo tàng Lâm Đồng là chỗ trú mưa lý tưởng, vừa khô ráo vừa hiểu thêm về vùng đất này."
    },
    {
      "poi_id": "p49",
      "kind": "activity",
      "must_do_id": null,
      "note": "Mây Lang Thang cho buổi cà phê chiều, ngồi trong nhà nhìn phố mưa qua cửa kính."
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tối đến thì nem nướng Bà Hùng, ngồi bàn trong nhà cuốn rau thịt nóng hổi, ngon quá."
    },
    {
      "poi_id": "p144",
      "kind": "activity",
      "must_do_id": null,
      "note": "Marché là chỗ vui chơi trong nhà cho buổi tối, khỏi lo mưa gió ngoài kia."
    }
  ]
}
```

